        """Remove dot segments from a path per RFC 3986 section 5.2.4."""
        if not path:
            return path

        # We need to handle the path carefully
        # RFC 3986: input buffer, output buffer
        input_buf = path
        output_buf = []

        while input_buf:
            # A. If the input buffer begins with a prefix of "../" or "./", then remove that prefix from the input buffer; otherwise,
            if input_buf.startswith('../'):
                input_buf = input_buf[3:]
            elif input_buf.startswith('./'):
                input_buf = input_buf[2:]
            # B. If the input buffer begins with a prefix of "/./" or if the input buffer is exactly a "/." followed by a "/", then replace that prefix with "/" in the input buffer; otherwise,
            elif input_buf.startswith('/./'):
                input_buf = '/' + input_buf[3:]
            elif input_buf == '/.':
                input_buf = '/'
            # C. If the input buffer begins with a prefix of "/../" or if the input buffer is exactly a "/.." followed by a "/", then replace that prefix with "/" in the input buffer and remove the last segment and its preceding "/" (if any) from the output buffer; otherwise,
            elif input_buf.startswith('/../'):
                input_buf = '/' + input_buf[4:]
                if output_buf:
                    output_buf.pop()
            elif input_buf == '/..':
                input_buf = '/'
                if output_buf:
                    output_buf.pop()
            # D. If the input buffer consists only of "." or "..", then remove that from the input buffer; otherwise,
            elif input_buf in ('.', '..'):
                input_buf = ''
            # E. Move the first path segment in the input buffer to the end of the output buffer. That includes the initial "/" character (if any) and any characters up to, but not including, the next "/" character or the end of the input buffer.
            else:
                slash_pos = input_buf.find('/')
                if slash_pos == -1:
                    output_buf.append(input_buf)
                    input_buf = ''
                else:
                    output_buf.append(input_buf[:slash_pos + 1])
                    input_buf = input_buf[slash_pos + 1:]

