            if ref_query:
                return (base_scheme, base_netloc, base_path, ref_query, ref_frag)
            else:
                return (base_scheme, base_netloc, base_path, base_query, ref_frag)

        # ref_path is not empty
        if ref_path.startswith('/'):
            # Absolute path
            return (base_scheme, base_netloc, ref_path, ref_query, ref_frag)

        # Relative path
        # Merge base path and reference path
        if base_netloc and not base_path:
            # Base path is empty, so just use / + ref_path
            merged_path = '/' + ref_path
        else:
            # Remove everything after the last '/' in base path
            last_slash = base_path.rfind('/')
            if last_slash == -1:
                # No slash in base path, just use ref_path
                merged_path = ref_path
            else:
                merged_path = base_path[:last_slash + 1] + ref_path

        return (base_scheme, base_netloc, merged_path, ref_query, ref_frag)

    def url_to_string(scheme, netloc, path, query, fragment):
        """Convert URL components back to a string."""
        result = ''
        if scheme:
            result += scheme + ':'
        if netloc:
            result += '//' + netloc
        result += path
        if query:
            result += '?' + query
        if fragment:
            result += '#' + fragment
        return result

    # Parse base and reference
    base_scheme, base_netloc, base_path, base_query, base_frag = parse_url(base)
    ref_scheme, ref_netloc, ref_path, ref_query, ref_frag = parse_url(url)

